def power(a, n, m):
    if n == 0:
        return 1
    half = power(a, n // 2, m)
    r = half * ___ % m
    if n % 2 == 1:
        r = r * a % m
    return r

long power(long a, long n, long m) {
    if (n == 0) return 1;
    long half = power(a, n / 2, m);
    long r = half * ___ % m;
    if (n % 2 == 1) r = r * a % m;
    return r;
}

function power(a, n, m) {  // BigInt
  if (n === 0n) return 1n;
  const half = power(a, n / 2n, m);
  let r = half * ___ % m;
  if (n % 2n === 1n) r = r * a % m;
  return r;
}

